SELECT id, title, detail, category, priority, due_date, completed, created_at, updated_at
FROM todos


        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND due_date >= #{from}


        AND due_date <= #{to}


ORDER BY due_date IS NULL,

    due_date DESC
    due_date ASC

SELECT id, title, detail, category, priority, due_date, completed, created_at, updated_at
FROM todos
WHERE id = #{id}
